def constructUniquePathGrid(m: int, n: int) -> list[list[int]]:
    grid = [[1] * n for _ in range(m)]
    # First row is free: (0, 0) -> (0, n-1)
    for c in range(n):
        grid[0][c] = 0
    # Last column is free: (0, n-1) -> (m-1, n-1)
    for r in range(m):
        grid[r][n - 1] = 0
    return grid

#include <vector>

class Solution {
public:
    std::vector<std::vector<int>> constructUniquePathGrid(int m, int n) {
        std::vector<std::vector<int>> grid(m, std::vector<int>(n, 1));
        for (int c = 0; c < n; ++c) grid[0][c] = 0;
        for (int r = 0; r < m; ++r) grid[r][n - 1] = 0;
        return grid;
    }
};

class Solution {
    public int[][] constructUniquePathGrid(int m, int n) {
        int[][] grid = new int[m][n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) grid[r][c] = 1;
        }
        for (int c = 0; c < n; c++) grid[0][c] = 0;
        for (int r = 0; r < m; r++) grid[r][n - 1] = 0;
        return grid;
    }
}

function constructUniquePathGrid(m, n) {
    const grid = Array.from({ length: m }, () => new Array(n).fill(1));
    for (let c = 0; c < n; c++) grid[0][c] = 0;
    for (let r = 0; r < m; r++) grid[r][n - 1] = 0;
    return grid;
}
